// ═══════════════════════════════════════════════════════════════════
// CUSTOMER NOTIFIER v2 — Salla order.status.updated → WhatsApp للعميل
// v2 (2026-07-04): تجاهل بدون أخطاء، منع التكرار عبر ذاكرة الوركفلو،
// الكمية تُحسب مع quantity، رسائل معاد صياغتها (ودّية + احترافية).
// ملاحظة: منع التكرار يعمل في التشغيل الحقيقي فقط (وليس في Test workflow).
// ═══════════════════════════════════════════════════════════════════
const inputJson = $input.all()[0]?.json || {};
const body = inputJson.body || inputJson;

const skip = (reason) => [{ json: { shouldSend: false, skipReason: reason } }];

if (body.event !== 'order.status.updated') return skip('event: ' + (body.event || 'unknown'));

const statusData = body.data || {};
const orderData = statusData.order;
if (!orderData) return skip('no order data');

const orderRefId = orderData.reference_id || orderData.id;
const statusName = (statusData.customized?.name || statusData.status || orderData.status?.customized?.name || orderData.status?.name || '').trim();
if (!statusName) return skip('no status name');

// ── رقم الجوال ──
let finalMobile = '';
const customerMobile = (orderData.customer?.mobile || '').toString().trim();
if (customerMobile.startsWith('+') || customerMobile.startsWith('00')) {
  finalMobile = customerMobile.replace('+', '').replace(/^00/, '');
} else {
  let mobileCode = (orderData.customer?.mobile_code || '').replace('+', '');
  let mobileNum = customerMobile;
  if (mobileNum.startsWith('0')) mobileNum = mobileNum.substring(1);
  finalMobile = mobileCode + mobileNum;
}
finalMobile = finalMobile.replace(/\D/g, '');
if (finalMobile.length < 9) return skip('no valid mobile');

// ── تحليل المنتجات والكمية (v2: الكمية × quantity) ──
const allItems = orderData.items || [];
let amountK = 0;
let productNames = [];
let properLink = '';
for (const itm of allItems) {
  const s = (itm.sku || '').toUpperCase();
  const n = (itm.name || '').toLowerCase();
  const qty = Number(itm.quantity) || 1;
  for (const opt of (itm.options || [])) {
    if ((opt.name || '').includes('الكمية') || (opt.name || '').includes('Amount')) {
      const valStr = (typeof opt.value === 'object' && opt.value !== null) ? String(opt.value.name || '') : String(opt.value || '');
      const match = valStr.replace(/,/g, '').match(/(\d+(\.\d+)?)/);
      if (match) {
        let num = parseFloat(match[0]);
        if (valStr.includes('مليون')) num *= 1000;
        amountK += num * qty;
      }
    }
  }
  if (s.includes('COIN') || n.includes('كوينز')) { productNames.push(itm.name); properLink = `https://track.arab-ut.com/?id=${orderRefId}`; }
  else if (s.includes('FUT')) { productNames.push(itm.name); }
  else if (s.includes('RIVALS')) { productNames.push(itm.name); }
  else if (s.includes('SBC')) { productNames.push(itm.name); properLink = `https://track.arab-ut.com/?id=${orderRefId}`; }
}
const productName = productNames.length ? productNames.join(' و ') : 'طلبك';

let amountText = '';
if (amountK >= 1000) amountText = `${Math.round((amountK / 1000) * 100) / 100} مليون`;
else if (amountK > 0) amountText = `${amountK} ألف`;

// ── العناصر المشتركة ──
const customerName = orderData.customer?.full_name || orderData.customer?.name || orderData.customer?.first_name || '';
const firstName = customerName ? customerName.trim().split(/\s+/)[0] : '';
const msgHeader = firstName ? `أهلاً ${firstName} 👋` : 'أهلاً بك 👋';

const trackSection = properLink ? `\n\n📝 تابع تفاصيل طلبك من هنا:\n${properLink}` : '';
// رابط الطلب — العميل يصلّح المشكلة ثم يضغط «تشغيل الطلب» بنفسه (بدل ما يرد "تم")
const resumeLink = `https://track.arab-ut.com/?id=${orderRefId}`;
const editSteps = `2️⃣ افتح رابط طلبك، عدّل البيانات، ثم اضغط زر «تشغيل الطلب» وبيكمل تلقائياً:\n${resumeLink}`;

const postCoinsRules = `⚠️ تعليمات مهمة بعد الشحن:\n1️⃣ لا تشحن كوينز من أي مصدر آخر ولا تنقل كوينز خارج حسابك.\n2️⃣ ننصح بتغيير كلمة مرور حساب EA الآن.\n\n🔴 المتجر غير مسؤول في حال عدم الالتزام بالتعليمات.`;
const successFooter = `شكراً لثقتك ❤️ تقييمك يفرّق معنا ⭐\nhttps://arab-ut.com/orders\n\nعشان ما تفوتك العروض وتوزيعات الكوينز المجانية، انضم لقناتنا 👇\nhttps://whatsapp.com/channel/0029Vb78lrKC6ZvnWN1z7t2h`;

// ── منطق الرسائل ──
let msgBody = '';
let sendWhatsApp = true;

if (statusName.includes('تم الانتهاء') || statusName.includes('بالرانك المطلوب') || statusName.includes('تم شحن') || statusName.includes('تم الشحن')) {
  const hasCoins = productName.includes('كوينز');
  const hasService = productName.includes('تحدي') || productName.includes('فوت') || productName.includes('رايفلز') || productName.toUpperCase().includes('SBC');
  const serviceLabel = productNames.filter(p => !(p || '').includes('كوينز')).join(' و ') || productName;
  const coinsPart = hasCoins ? `🎉 تم شحن ${amountText ? amountText + ' ' : ''}كوينز بنجاح — طلب #${orderRefId}\n\n${postCoinsRules}` : '';
  const svcPart = hasService ? `✅ تم تنفيذ طلبك (${serviceLabel}) بنجاح — طلب #${orderRefId}\n\nنتمنى لك حظاً موفقاً في الجوائز 🎁\n🔒 لأمان حسابك: غيّر كلمة مرور حساب EA الآن.` : '';
  if (coinsPart && svcPart) msgBody = `${coinsPart}\n\n${svcPart}\n\n${successFooter}`;
  else if (coinsPart) msgBody = `${coinsPart}\n\n${successFooter}`;
  else if (svcPart) msgBody = `${svcPart}\n\n${successFooter}`;
  else msgBody = `✅ تم تنفيذ طلبك (${productName}) بنجاح — طلب #${orderRefId}\n\n🔒 لأمان حسابك: غيّر كلمة مرور حساب EA الآن.\n\n${successFooter}`;
}
else if (statusName.includes('جاري شحن الكوينز')) {
  msgBody = `🚀 بدأنا شحن الكوينز — طلب #${orderRefId}\n\n⚠️ مهم جداً: لا تدخل على حسابك نهائياً حتى تصلك رسالة الانتهاء — الدخول أثناء الشحن يوقف العملية.${trackSection}`;
}
else if (statusName.includes('ارسال بيانات الحساب للمحترف') || statusName.includes('جاري الانتهاء من التحدي')) {
  msgBody = `👨‍💻 المختص استلم طلبك (${productName}) — طلب #${orderRefId}\n\nجاري العمل عليه الآن، وبنرسل لك فور الانتهاء.${trackSection}`;
}
else if (statusName.includes('ايميل') || statusName.includes('باسورد')) {
  msgBody = `❌ ما قدرنا ندخل على حساب EA — طلب #${orderRefId}\n\nبيانات الدخول (الإيميل أو كلمة المرور) غير صحيحة.\n\nالمطلوب:\n1️⃣ تأكد من الإيميل وكلمة المرور (جرّب تدخل بنفسك مرة للتأكد).\n${editSteps}`;
}
else if (statusName.includes('كمية') && statusName.includes('قليلة')) {
  msgBody = `⚠️ رصيد الكوينز في حسابك غير كافي — طلب #${orderRefId}\n\nلبدء النقل الآمن لازم يتوفر في حسابك 6000 كوينز على الأقل.\n\nالمطلوب:\n1️⃣ وفّر المبلغ (العب مباراة أو بِع لاعب من النادي).\n2️⃣ بعدها افتح رابط طلبك واضغط زر «تشغيل الطلب» وبيكمل تلقائياً:\n${resumeLink}`;
}
else if (statusName.includes('مسجل الدخول')) {
  msgBody = `⚠️ الحساب مسجّل دخول — طلب #${orderRefId}\n\nما نقدر نبدأ شغل وأنت متصل بالحساب.\n\nالحل السريع:\n1️⃣ ادخل اللعبة من جهازك.\n2️⃣ ادخل الألتميت تيم (Ultimate Team).\n3️⃣ اطلع للقائمة الرئيسية بشكل نظامي.\n4️⃣ تأكد إنك مقفّل تطبيق الجوال (Companion App) تماماً.\n\nوبعدها افتح رابط طلبك واضغط زر «تشغيل الطلب» وفالك التوفيق:\n${resumeLink}`;
}
else if (statusName.includes('منصة')) {
  msgBody = `🛑 المنصة المختارة غير مطابقة — طلب #${orderRefId}\n\nيبدو أنك اخترت منصة (سوني / إكس بوكس / PC) مختلفة عن منصة حسابك الفعلية.\n\nالمطلوب:\n1️⃣ تأكد من منصة حسابك.\n${editSteps}`;
}
else if (statusName.includes('مقفول') || statusName.includes('سوق')) {
  msgBody = `⛔ سوق الانتقالات غير متاح في حسابك — طلب #${orderRefId}\n\nحسابك ما زال بدون صلاحية السوق في تطبيق/ويب الألتيميت تيم (تفتحها EA عادة بعد ساعات لعب كافية داخل اللعبة).\n\nالمطلوب:\n1️⃣ افتح السوق من داخل اللعبة أولاً.\n2️⃣ بعدها افتح رابط طلبك واضغط زر «تشغيل الطلب» وبيكمل تلقائياً:\n${resumeLink}`;
}
else if (statusName.includes('أكواد')) {
  msgBody = `❌ الأكواد الاحتياطية غير صحيحة — طلب #${orderRefId}\n\nالمطلوب:\n1️⃣ استخرج أكواد جديدة وتأكد أنها باللون الأسود (غير مستخدمة).\n2️⃣ افتح رابط طلبك، حدّث الأكواد، ثم اضغط زر «تشغيل الطلب»:\n${resumeLink}\n\n🎥 طريقة الاستخراج:\nhttps://arab-ut.com/ea-backup-codes-guide/page-699997932`;
}
else if (statusName.includes('ملغي') || statusName.includes('ملغى') || statusName.includes('إلغاء') || statusName.includes('مسترجع') || statusName.includes('استرجاع') || statusName.includes('الإسترجاع')) {
  msgBody = `🛑 تحديث بخصوص طلبك #${orderRefId}\n\nتم إلغاء الطلب أو استرجاعه.\nتقدر تشوف تفاصيل الطلب والمبلغ من صفحة طلبك:\n${resumeLink}`;
}
else {
  // قيد التنفيذ / تم التنفيذ / جاري التوصيل / أي حالة غير معروفة → لا رسالة
  sendWhatsApp = false;
}

if (!sendWhatsApp) return skip('status not notifiable: ' + statusName);

// ── منع التكرار: نفس الطلب + نفس الحالة خلال 6 ساعات → رسالة واحدة فقط ──
try {
  const sd = $getWorkflowStaticData('global');
  sd.sentLog = sd.sentLog || {};
  const now = Date.now();
  for (const k of Object.keys(sd.sentLog)) {
    if (now - sd.sentLog[k] > 48 * 3600 * 1000) delete sd.sentLog[k];
  }
  const dedupKey = `${orderData.id || orderRefId}|${statusName}`;
  if (sd.sentLog[dedupKey] && now - sd.sentLog[dedupKey] < 6 * 3600 * 1000) {
    return skip('duplicate: ' + dedupKey);
  }
  sd.sentLog[dedupKey] = now;
} catch (e) {}

const finalMessage = `${msgHeader}\n\n${msgBody}`;

return [{ json: {
  mobile: finalMobile,
  message: finalMessage,
  shouldSend: true,
  orderId: orderRefId,
  statusName,
} }];
